const FULL_FIELDS:&[u64]=&[1154,32768,65536,131072,262144,524288,1048576,2097152,4194304,8388608,16777216,33554432,67108864,134217728,134218882,268435456,536870912,1073741824,2147483648,4294967296,8589934592];
pub(super)fn full_fold(c:&mut Builder,acc:&[QubitId],e:[QubitId;3],nm:[QubitId;3],k1:QubitId,k2:QubitId,target:usize)->Vec<usize>{
 assert_eq!(acc.len(),56);let input:Vec<_>=acc[..6].iter().copied().chain(e).chain(nm).chain([k1,k2]).collect();let active=c.active_qubits();let held=build(c,&input);let wires:Vec<_>=input.iter().chain(&held).copied().collect();let fields:Vec<_>=FULL_FIELDS.iter().map(|&v|form(&wires,v)).collect();let add=field_map(&fields[..6],&fields[6..13],&fields[13],&fields[14..],acc.len());let budget=target.saturating_sub(c.active_qubits()as usize);let(plan,drops)=if budget==8{(Y28_PLAN8.0.to_vec(),Y28_PLAN8.1.to_vec())}else if budget==9{(Y28_PLAN9.0.to_vec(),Y28_PLAN9.1.to_vec())}else{assert!(budget>=10,"Prefix27 full fold needs at least8 ladder wires");let p=match merged_plan(49,budget){Some(mut p)=>{*p.last_mut().unwrap()+=1;p},None=>merged_plan(50,budget).expect("prefix27 ladder budget")};(p,Vec::new())};ladder_d(c,acc,&add,6,held[19],&plan,&drops);finish(c,&input,&held);assert_eq!(c.active_qubits(),active);plan
}
